insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_65_v1'
from (values
('127.412.d.1',3,'An engineer notices that a supplier substituted a weaker alloy in a safety-critical part. The ethical response is to:','["report the substitution and stop use of the part", "ignore it to save time", "use it anyway", "keep it secret"]'::jsonb,0,'Engineers hold public safety paramount.','original'),
('127.412.d.1',4,'Using another company''s confidential design files without permission violates professional ethics because it breaks rules of:','["punctuation", "intellectual property and confidentiality", "fashion", "scheduling only"]'::jsonb,1,'Engineers must respect others'' proprietary work.','original'),
('127.412.d.2.A',3,'A team that works through problem definition, research, ideas, prototype, test, and redesign is following an:','["accounting cycle", "payroll plan", "engineering design process", "grading scale"]'::jsonb,2,'A process gives structure to design work.','original'),
('127.412.d.2.A',4,'Implementing the design process on a school project means the team documents each stage and uses test results to:','["avoid testing", "hide mistakes", "skip the research", "guide improvements"]'::jsonb,3,'Evidence drives each iteration.','original'),
('127.412.d.2.B',3,'A project with many interacting subsystems and a long list of requirements is described as having high:','["complexity", "silence", "humor", "color"]'::jsonb,0,'Complexity depends on parts and interactions.','original'),
('127.412.d.2.B',4,'Limited time, money, and tools available to a team are its:','["trophies", "resources", "opinions", "hobbies"]'::jsonb,1,'Resources limit how a design can be developed.','original'),
('127.412.d.2.C',3,'A stakeholder in an engineering project is any person or group that is:','["only the designer", "unrelated to it", "affected by or has an interest in the design", "only the boss"]'::jsonb,2,'Stakeholders include users, owners, and neighbors.','original'),
('127.412.d.2.C',4,'Ignoring the needs of a major stakeholder early in design often causes:','["lower risk", "fewer requirements", "faster approval", "costly redesign later"]'::jsonb,3,'Missed needs surface late and cost more to fix.','original'),
('127.412.d.2.D',3,'When a prototype breaks during testing, an engineer can learn:','["what limits must be addressed in the next version", "nothing useful", "to stop testing", "who to blame"]'::jsonb,0,'Failure reveals weaknesses.','original'),
('127.412.d.2.D',4,'A team that treats a failed test as useful data is demonstrating that failure can be:','["a final result", "an essential part of the design process", "always avoidable", "a reason to quit"]'::jsonb,1,'Learning from failure leads to better designs.','original'),
('127.412.d.3.A',3,'Project management commonly includes initiating, planning, executing, monitoring, and:','["forgetting", "retreating", "closing", "ignoring"]'::jsonb,2,'Closing completes the project phases.','original'),
('127.412.d.3.A',4,'The planning phase of a project is where a team defines scope, schedule, and:','["slogan", "uniform", "mascot", "budget"]'::jsonb,3,'Planning sets the baseline for execution.','original'),
('127.412.d.3.B',3,'On an engineering team, the project manager is mainly responsible for:','["coordinating people, schedule, and resources", "choosing paint colors", "deleting records", "building every part alone"]'::jsonb,0,'Managers keep the project on track.','original'),
('127.412.d.3.B',4,'A team member who owns analysis of a specific subsystem has a defined:','["hobby", "role and responsibility", "vacation", "nickname"]'::jsonb,1,'Clear roles prevent gaps and overlap.','original'),
('127.412.d.3.C',3,'Software that shows tasks, owners, and due dates in one place is a project:','["cooking tool", "music tool", "management tool", "paint tool"]'::jsonb,2,'Such tools track progress.','original'),
('127.412.d.3.C',4,'When comparing project management tools, a team should consider team size, cost, and how well the tool fits the:','["building color", "team members'' pets", "weather", "project needs"]'::jsonb,3,'Tools should match the work.','original'),
('127.412.d.3.D',3,'Storing design files in a shared folder with version names helps a team control:','["document revisions", "lunch orders", "fashion choices", "parking"]'::jsonb,0,'Version control prevents using outdated files.','original'),
('127.412.d.3.D',4,'A system for naming and storing documents is important because it lets team members find:','["only old drafts", "the latest approved version", "random notes", "nothing"]'::jsonb,1,'Organization prevents errors.','original'),
('127.412.d.3.E',3,'A requirement that a product weigh under 2 kg is a:','["delivered report", "finished product", "constraint on the design", "guess"]'::jsonb,2,'Requirements and constraints limit solutions.','original'),
('127.412.d.3.E',4,'Project deliverables are best defined early because they determine:','["the room temperature", "who wins", "the team name", "what the team must produce"]'::jsonb,3,'Deliverables shape the work plan.','original'),
('127.412.d.3.F',3,'A project budget lists expected costs for materials, equipment, and:','["labor", "rumors", "weather", "dreams"]'::jsonb,0,'Labor is a major cost.','original'),
('127.412.d.3.F',4,'If a project''s actual spending exceeds its budget, the manager should first:','["ignore it", "identify why and adjust the plan", "spend more", "hide the numbers"]'::jsonb,1,'Variance analysis guides corrections.','original'),
('127.412.d.3.G',3,'Management of change (MOC) is a process for:','["making changes secretly", "avoiding all changes", "reviewing and approving modifications before they are made", "forgetting changes"]'::jsonb,2,'MOC controls risk from changes.','original'),
('127.412.d.3.G',4,'An uncontrolled change to a design late in a project can affect cost, schedule, and:','["music", "weather", "lunch", "safety"]'::jsonb,3,'Changes ripple through a project.','original'),
('127.412.d.4.A',3,'Sensemaking on a team includes recognizing each member''s strengths and:','["assigning tasks that fit them", "choosing at random", "ignoring them", "avoiding teamwork"]'::jsonb,0,'Using strengths improves results.','original'),
('127.412.d.4.A',4,'Active listening during a team meeting helps members to:','["talk over each other", "understand each other''s ideas", "multitask only", "skip meetings"]'::jsonb,1,'Listening builds shared understanding.','original'),
('127.412.d.4.B',3,'An Agile approach breaks a project into short cycles called:','["parades", "naps", "sprints", "lectures"]'::jsonb,2,'Sprints deliver work in increments.','original'),
('127.412.d.4.B',4,'A work breakdown structure helps a team by dividing the project into:','["colors", "teams only", "rooms", "manageable tasks"]'::jsonb,3,'Smaller tasks are easier to assign and track.','original'),
('127.412.d.4.C',3,'The critique steps of describing, analyzing, interpreting, and evaluating are used to:','["give structured feedback", "tease others", "grade by feeling", "avoid feedback"]'::jsonb,0,'Structured critique stays objective.','original'),
('127.412.d.4.C',4,'In a structured critique, the interpreting step explains what an observed feature:','["looks like only", "means for the design", "sounds like", "costs to print"]'::jsonb,1,'Interpretation links observation to purpose.','original'),
('127.412.d.4.D',3,'An action plan that lists who will do what by when helps a team:','["lose track", "skip tasks", "follow through on improvements", "avoid decisions"]'::jsonb,2,'Action plans make feedback actionable.','original'),
('127.412.d.4.D',4,'A good action plan states each task, an owner, and a:','["nickname", "favorite song", "lunch", "due date"]'::jsonb,3,'Deadlines create accountability.','original'),
('127.412.d.4.E',3,'An effective critique of a teammate''s drawing is specific, respectful, and focused on the:','["work", "person", "teammate''s age", "teammate''s appearance"]'::jsonb,0,'Critique the work, not the person.','original'),
('127.412.d.4.E',4,'Instead of saying ''this is bad'', an effective critique would say:','["''I do not like it''", "''the dimensions are missing, so it cannot be built''", "''you are not good at this''", "''whatever''"]'::jsonb,1,'Specific, evidence-based comments help.','original'),
('127.412.d.4.F',3,'When critiquing another team''s design, a respectful approach is to start by:','["listing only flaws", "staying silent", "noting what works well", "laughing"]'::jsonb,2,'Balanced feedback is better received.','original'),
('127.412.d.4.F',4,'Feedback to another team should be tied to the team''s stated:','["lunch plans", "opinions about the room", "favorite colors", "requirements"]'::jsonb,3,'Requirements provide an objective standard.','original'),
('127.412.d.4.G',3,'After receiving critique, a team should sort comments into those that:','["can improve the design and those that cannot", "come from friends only", "should be erased", "are all wrong"]'::jsonb,0,'Evaluate critique for usefulness.','original'),
('127.412.d.4.G',4,'A team gets conflicting critique from two reviewers. The team should:','["choose at random", "check the requirements to decide", "ignore both", "argue with reviewers"]'::jsonb,1,'Requirements help resolve conflicts.','original'),
('127.412.d.4.H',3,'A design review presentation should show current status and ask for:','["applause only", "a new team", "feedback", "silence"]'::jsonb,2,'Reviews solicit input.','original'),
('127.412.d.4.H',4,'At a design review, showing risks and open questions helps reviewers to:','["leave early", "skip the review", "feel confused", "give useful suggestions"]'::jsonb,3,'Transparency improves feedback.','original'),
('127.412.d.5.A',3,'A short summary at the front of a report that gives key findings is an:','["executive summary", "glossary", "index", "appendix"]'::jsonb,0,'It tells busy readers the main points.','original'),
('127.412.d.5.A',4,'A reverse engineering form records what was learned from:','["sales receipts", "taking apart an existing product", "weather data", "school lunches"]'::jsonb,1,'Forms capture disassembly findings.','original'),
('127.412.d.5.B',3,'A table is a better format than a paragraph for presenting:','["a joke", "a greeting", "many values to compare", "a story"]'::jsonb,2,'Tables organize data.','original'),
('127.412.d.5.B',4,'A drawing is the best format to communicate:','["a team vote", "a budget memo", "a meeting reminder", "the shape and dimensions of a part"]'::jsonb,3,'Drawings show geometry.','original'),
('127.412.d.5.C',3,'A report''s information should be sequenced so readers can follow it from the problem to the:','["solution and results", "cover design", "lunch", "weather"]'::jsonb,0,'Logical order aids understanding.','original'),
('127.412.d.5.C',4,'Placing background before the solution in a report is justified because readers need to understand the:','["title only", "context first", "color scheme", "answer last always"]'::jsonb,1,'Context supports the solution.','original'),
('127.412.d.5.D',3,'An assembly manual should list steps in the order:','["parts are named", "parts are priced", "parts are put together", "parts are bought"]'::jsonb,2,'Sequence matters in assembly.','original'),
('127.412.d.5.D',4,'Peer review of a user manual helps find steps that are:','["too heavy", "too colorful", "too short only", "unclear or missing"]'::jsonb,3,'Fresh eyes spot gaps.','original'),
('127.412.d.5.E',3,'A final design report should explain the project scope and the:','["solution that was developed", "school mascot", "team''s snacks", "daily weather"]'::jsonb,0,'It documents the outcome.','original'),
('127.412.d.5.E',4,'A final design report includes evidence such as test results because evidence:','["fills space", "supports the claims made", "replaces drawings", "is optional decoration"]'::jsonb,1,'Data justifies conclusions.','original'),
('127.412.d.6.A',3,'A project management plan lists tasks, durations, and the:','["weather forecast", "team''s playlists", "deliverables due at each point", "office furniture"]'::jsonb,2,'Plans tie time to outputs.','original'),
('127.412.d.6.A',4,'A schedule that shows task B cannot start until task A finishes includes a:','["mascot", "slogan", "rumor", "dependency"]'::jsonb,3,'Dependencies order the tasks.','original'),
('127.412.d.6.B',3,'A project plan should be reviewed periodically because conditions and progress:','["change over time", "are always identical", "do not matter", "never change"]'::jsonb,0,'Plans need updates.','original'),
('127.412.d.6.B',4,'If testing shows a task will take twice as long, the manager should update the plan and tell the:','["no one", "affected team members and stakeholders", "neighbors only", "competition"]'::jsonb,1,'Communicating changes avoids surprises.','original'),
('127.412.d.6.C',3,'A test proposal describes what will be tested, how it will be tested, and what is needed to:','["avoid the test", "lose the data", "approve and run the test", "skip analysis"]'::jsonb,2,'Proposals are reviewed before testing.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_65_v1'
from (values
('127.412.d.6.C',4,'A model proposal should explain what the model will show and what question it will:','["hide", "paint", "avoid", "help answer"]'::jsonb,3,'Models serve a purpose.','original'),
('127.412.d.6.D',3,'Stage-gate project management divides work into stages separated by:','["review gates", "naps", "parties", "costumes"]'::jsonb,0,'A gate decides whether to proceed.','original'),
('127.412.d.6.D',4,'Compared with stage-gate, Agile management emphasizes:','["no customers", "short cycles with frequent feedback", "one final review only", "no planning"]'::jsonb,1,'Agile iterates quickly.','original'),
('127.412.d.7.A',3,'An engineer''s professional responsibility to stakeholders includes protecting their:','["weather", "gossip", "health and safety", "fashion"]'::jsonb,2,'Safety is the first duty.','original'),
('127.412.d.7.A',4,'An engineer who learns a design could harm users should inform the:','["nobody", "competition", "press only", "responsible stakeholders"]'::jsonb,3,'Disclosure is part of responsibility.','original'),
('127.412.d.7.B',3,'A journey map shows the steps a stakeholder takes while:','["using a product or service", "traveling by air only", "shopping for shoes", "sleeping"]'::jsonb,0,'Journey maps model experiences.','original'),
('127.412.d.7.B',4,'A journey map can reveal moments of frustration, which become opportunities for:','["delay", "design improvement", "advertising", "hiding"]'::jsonb,1,'Pain points guide design.','original'),
('127.412.d.7.C',3,'Staying in contact with stakeholders throughout a project helps ensure the design still meets their:','["hobbies", "pets", "needs", "birthdays"]'::jsonb,2,'Needs can shift over time.','original'),
('127.412.d.7.C',4,'A stakeholder who is not consulted until the end may reject the design because it:','["has too many options", "is too perfect", "costs too little", "does not meet their expectations"]'::jsonb,3,'Early engagement avoids surprises.','original'),
('127.412.d.8.A',3,'One way to learn what users need is to hold an:','["interview", "audit of the lunch menu", "raffle", "auction"]'::jsonb,0,'Interviews collect requirements.','original'),
('127.412.d.8.A',4,'A survey given to likely users helps the team gather stakeholder:','["autographs", "requirements", "trophies", "jokes"]'::jsonb,1,'Surveys collect needs at scale.','original'),
('127.412.d.8.B',3,'Requirements are refined through interviews, prototyping, and:','["gossip", "napping", "testing", "coloring"]'::jsonb,2,'Evidence improves requirements.','original'),
('127.412.d.8.B',4,'Requirements should be documented so the team can trace each design decision back to a:','["coin flip", "rumor", "preference for color", "stated need"]'::jsonb,3,'Traceability supports choices.','original'),
('127.412.d.8.C',3,'A well-written requirement uses the word ''shall'' and states something that can be:','["verified", "guessed", "argued only", "ignored"]'::jsonb,0,'Requirements must be testable.','original'),
('127.412.d.8.C',4,'''The device shall operate for 8 hours on one charge'' is a good requirement because it is:','["unrelated", "measurable", "flexible", "vague"]'::jsonb,1,'Numbers allow verification.','original'),
('127.412.d.8.D',3,'Checking that every requirement traces to at least one stakeholder prevents:','["good ideas", "documentation", "requirements nobody asked for", "all testing"]'::jsonb,2,'Each requirement needs a source.','original'),
('127.412.d.8.D',4,'A requirement with no stakeholder source should be:','["automatically approved", "hidden", "doubled", "questioned and possibly removed"]'::jsonb,3,'Unneeded requirements add cost.','original'),
('127.412.d.8.E',3,'Checking that every stakeholder is represented by at least one requirement prevents:','["ignoring a group''s needs", "good teamwork", "too many tests", "extra drawings"]'::jsonb,0,'Every stakeholder deserves coverage.','original'),
('127.412.d.8.E',4,'If a stakeholder has no matching requirement, the team likely:','["can skip testing", "missed a need", "finished early", "has perfect requirements"]'::jsonb,1,'A gap signals incomplete requirements.','original'),
('127.412.d.8.F',3,'Each requirement should be linked to the part of the design that satisfies it, called the:','["slogan", "mood", "design element", "rumor"]'::jsonb,2,'Linking shows how requirements are met.','original'),
('127.412.d.8.F',4,'Linking requirements to test methods helps the team prove that the design:','["is famous", "is cheap", "is attractive", "meets the requirement"]'::jsonb,3,'Verification confirms requirements.','original'),
('127.412.d.8.G',3,'A mechanical requirement that a housing stay below 40 degrees Celsius draws on the concept of:','["heat transfer", "sociology", "optics", "genetics"]'::jsonb,0,'Cooling depends on heat transfer.','original'),
('127.412.d.8.G',4,'A requirement that a bracket not bend under load draws on mechanics of:','["feelings", "materials", "languages", "fashion"]'::jsonb,1,'Stress and strain determine bending.','original'),
('127.412.d.8.H',3,'Requirements drive a project because every design choice must:','["ignore them", "avoid them", "satisfy them", "replace them"]'::jsonb,2,'Requirements guide decisions.','original'),
('127.412.d.8.H',4,'If requirements change midway, the team must revisit the:','["lunch menu", "parking plan", "team photos", "design and schedule"]'::jsonb,3,'Changes ripple through the work.','original'),
('127.412.d.9.A',3,'A sketch showing the parts of a lever system is a basic:','["model of a mechanical concept", "diary", "map of a city", "menu"]'::jsonb,0,'Models represent concepts.','original'),
('127.412.d.9.A',4,'A simple spring-and-mass drawing is used to model a:','["weather pattern", "vibrating system", "election", "cooking process"]'::jsonb,1,'This is a standard vibration model.','original'),
('127.412.d.9.B',3,'Comparing a model''s predicted performance with a requirement tells the team whether the model:','["is colorful", "is large", "meets the requirement", "is expensive"]'::jsonb,2,'Models are checked against requirements.','original'),
('127.412.d.9.B',4,'A model predicts a part will bend 5 mm but the requirement allows 2 mm. The concept:','["passes", "needs no change", "is finished", "does not yet meet the requirement"]'::jsonb,3,'5 mm exceeds 2 mm.','original'),
('127.412.d.9.C',3,'Running a simulation can reveal a new requirement, such as a need for:','["extra cooling", "a new logo", "a longer title", "more paint"]'::jsonb,0,'Models expose needs.','original'),
('127.412.d.9.C',4,'A model shows a bracket vibrating at the motor''s speed. A new requirement might be to:','["make it louder", "avoid that resonance", "remove the bracket", "increase vibration"]'::jsonb,1,'Resonance should be avoided.','original'),
('127.412.d.9.D',3,'A clear diagram of a design is used to:','["confuse reviewers", "hide the solution", "communicate the solution to stakeholders", "delay approval"]'::jsonb,2,'Models communicate designs.','original'),
('127.412.d.9.D',4,'A 3D rendering is useful for non-technical stakeholders because it shows the design:','["in code", "without shape", "only in numbers", "in a form they can easily understand"]'::jsonb,3,'Visuals help non-experts.','original'),
('127.412.d.9.E',3,'The first law of thermodynamics is a statement of the conservation of:','["energy", "color", "price", "paint"]'::jsonb,0,'Energy is conserved.','original'),
('127.412.d.9.E',4,'The conservation of momentum states that in a closed system, total momentum:','["doubles", "stays constant", "vanishes", "randomly changes"]'::jsonb,1,'Momentum is conserved.','original'),
('127.412.d.9.F',3,'In a system model of a pump, the mass of fluid entering equals the mass leaving plus any mass:','["created from nothing", "added by color", "stored in the system", "lost to noise"]'::jsonb,2,'Mass is conserved.','original'),
('127.412.d.9.F',4,'Applying energy conservation to a motor model helps account for electrical energy converted into mechanical energy and:','["sound only", "new matter", "colors", "heat losses"]'::jsonb,3,'Energy balances include losses.','original'),
('127.412.d.10.A',3,'Selecting the key requirements for a problem helps the team focus on what:','["matters most", "nobody wants", "costs nothing", "matters least"]'::jsonb,0,'Key requirements drive concepts.','original'),
('127.412.d.10.A',4,'A key requirement is one that, if not met, would make the solution:','["cheaper", "unacceptable", "more colorful", "quieter"]'::jsonb,1,'Key requirements are essential.','original'),
('127.412.d.10.B',3,'In a morphological chart, each key requirement is listed with several different:','["colors", "dates", "means of satisfying it", "prices"]'::jsonb,2,'Charts list options per function.','original'),
('127.412.d.10.B',4,'A morphological chart helps teams avoid fixating on one idea by showing many:','["errors", "costs", "deadlines", "alternatives"]'::jsonb,3,'Charts broaden thinking.','original'),
('127.412.d.10.C',3,'Combining one means from each row of a morphological chart creates an:','["integrated solution", "budget", "empty box", "drawing error"]'::jsonb,0,'Combinations form concepts.','original'),
('127.412.d.10.C',4,'A concept built by picking one option from every row of the chart is called a:','["random guess", "complete concept", "single part", "partial sketch"]'::jsonb,1,'Each row contributes one element.','original'),
('127.412.d.10.D',3,'A chart has 3 means for function A and 4 means for function B. The total number of possible solutions is:','["34", "1", "12", "7"]'::jsonb,2,'3 x 4 = 12.','original'),
('127.412.d.10.D',4,'A chart has 5, 2, and 3 means in three rows. The number of possible combinations is:','["60", "10", "15", "30"]'::jsonb,3,'5 x 2 x 3 = 30.','original'),
('127.412.d.11.A',3,'A key rule of brainstorming is to avoid judging ideas during:','["idea generation", "lunch", "testing", "reports"]'::jsonb,0,'Deferred judgment encourages ideas.','original'),
('127.412.d.11.A',4,'In the 6-3-5 method, six people each write three ideas in five minutes and then:','["throw the sheet away", "pass the sheet to a neighbor", "read silently", "stop"]'::jsonb,1,'Ideas build on one another.','original'),
('127.412.d.11.B',3,'Using brainstorming on a problem such as keeping a backpack dry results in:','["no ideas", "one idea only", "multiple concepts", "a final product"]'::jsonb,2,'Ideation tools generate options.','original'),
('127.412.d.11.B',4,'Sketching quick ideas and sharing them for others to build on applies the tool called:','["filing", "accounting", "sorting", "gallery method"]'::jsonb,3,'Sharing sketches spreads ideas.','original'),
('127.412.d.11.C',3,'Ideation tools can be compared by the rules they use, the number of people involved, and how ideas are:','["represented", "sold", "priced", "weighed"]'::jsonb,0,'Tools differ in form and group size.','original'),
('127.412.d.11.C',4,'A tool that works well for one person alone is:','["group voting", "individual brainstorming", "gallery walk", "6-3-5"]'::jsonb,1,'6-3-5 and galleries use groups.','original'),
('127.412.d.12.A',3,'A decision matrix scores each concept against weighted criteria to help:','["avoid the work", "pick lunch", "remove weak concepts", "pick a team"]'::jsonb,2,'Matrices prune a large set.','original'),
('127.412.d.12.A',4,'In a weighted decision matrix, a criterion with a higher weight has:','["random influence", "no influence", "less influence", "more influence on the total score"]'::jsonb,3,'Weights reflect importance.','original'),
('127.412.d.12.B',3,'Pair-wise comparison prunes concepts by comparing them:','["two at a time", "by weight only", "by color", "all at once"]'::jsonb,0,'Each pair yields a winner.','original'),
('127.412.d.12.B',4,'In pair-wise comparison, the concept that wins the most pairings is:','["ignored", "ranked highest", "unchanged", "removed first"]'::jsonb,1,'Wins determine rank.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_65_v1'
from (values
('127.412.d.12.C',3,'A pro-con list prunes concepts by listing the advantages and the:','["team members'' names", "prices of lunch", "disadvantages of each", "weather"]'::jsonb,2,'Pros and cons compare ideas.','original'),
('127.412.d.12.C',4,'A concept with many serious cons and few pros is likely to be:','["painted", "chosen immediately", "doubled", "dropped from consideration"]'::jsonb,3,'Weak options are pruned.','original'),
('127.412.d.12.D',3,'Using more than one pruning tool is important because each tool can:','["reveal different strengths and weaknesses", "guarantee success", "give the same answer always", "replace testing"]'::jsonb,0,'Multiple tools reduce bias.','original'),
('127.412.d.12.D',4,'If two pruning tools disagree about a concept, the team should:','["ignore both", "investigate the reason for the difference", "flip a coin", "pick the cheaper one"]'::jsonb,1,'Disagreement signals something to examine.','original'),
('127.412.d.12.E',3,'Pruning tools help narrow concepts but are not meant to:','["reduce choices", "compare ideas", "make the final selection automatically", "organize options"]'::jsonb,2,'Judgment and testing must follow.','original'),
('127.412.d.12.E',4,'A matrix score is only an estimate, so after pruning the team still needs to:','["skip prototypes", "discard the matrix", "stop thinking", "test and evaluate the remaining concepts"]'::jsonb,3,'Testing confirms the choice.','original'),
('127.412.d.13.A',3,'A prototyping proposal estimates the cost, time, and effort needed to:','["build and test the prototype", "avoid the prototype", "hire a chef", "skip planning"]'::jsonb,0,'Proposals justify prototype work.','original'),
('127.412.d.13.A',4,'A proposal should state what question the prototype will help answer so reviewers can judge whether it is:','["colorful", "worth the effort", "loud", "popular"]'::jsonb,1,'Purpose justifies effort.','original'),
('127.412.d.13.B',3,'Choosing a low-cost material such as foam board for an early prototype is appropriate when the goal is to test:','["final strength", "final color", "shape and fit", "market price"]'::jsonb,2,'Early prototypes can be rough.','original'),
('127.412.d.13.B',4,'A 3D printer is a useful fabrication tool for prototypes because it can make:','["food", "electricity", "weather", "custom parts quickly"]'::jsonb,3,'Additive manufacturing speeds iteration.','original'),
('127.412.d.13.C',3,'A testing plan lists what to measure, how to measure it, and what result will count as a:','["pass", "joke", "guess", "trophy"]'::jsonb,0,'Tests need criteria.','original'),
('127.412.d.13.C',4,'After executing a test plan, the team should record the:','["mood only", "results and observations", "rumors", "weather"]'::jsonb,1,'Data supports decisions.','original'),
('127.412.d.13.D',3,'A prototype test may reveal a new requirement, such as a need for a:','["new logo", "longer title", "stronger hinge", "new name"]'::jsonb,2,'Testing uncovers needs.','original'),
('127.412.d.13.D',4,'New requirements discovered during testing should be added to the:','["poster", "shopping list", "lunch menu", "requirements document"]'::jsonb,3,'Documents stay current.','original'),
('127.412.d.13.E',3,'Each model or prototype should have a clear purpose tied to the:','["requirements it helps verify", "day of the week", "builder''s mood", "color of the table"]'::jsonb,0,'Purposeful models save time.','original'),
('127.412.d.13.E',4,'Building a full-scale prototype to answer a question a simple sketch could answer is:','["always best", "an inefficient use of resources", "free", "required"]'::jsonb,1,'Match the model to the question.','original'),
('127.412.d.14.A',3,'A geometric model shows the shape and size of parts, such as in a:','["recipe", "map of weather", "CAD drawing", "poem"]'::jsonb,2,'CAD represents geometry.','original'),
('127.412.d.14.A',4,'A drawing used to build a part must include its:','["autograph", "favorite color", "nickname", "dimensions"]'::jsonb,3,'Dimensions let others build it.','original'),
('127.412.d.14.B',3,'Finite element analysis software predicts how a part will respond to:','["loads", "jokes", "gossip", "music"]'::jsonb,0,'FEA simulates stress and strain.','original'),
('127.412.d.14.B',4,'Comparing simulation results with test data helps the team judge how accurately the model:','["costs", "predicts the real part", "is named", "looks good"]'::jsonb,1,'Correlation validates models.','original'),
('127.412.d.14.C',3,'A design decision to use aluminum instead of steel for a lighter product can be justified by the requirement for:','["longer name", "more color", "low weight", "higher density"]'::jsonb,2,'Requirements support decisions.','original'),
('127.412.d.14.C',4,'Design decisions should be justified using requirements such as functionality, cost, and:','["weather", "rumors", "hobbies", "safety"]'::jsonb,3,'Justification uses criteria.','original'),
('127.412.d.14.D',3,'A final prototype is fabricated using the tools and materials chosen to:','["match the final design", "match last year''s design", "impress guests", "avoid testing"]'::jsonb,0,'The final prototype represents the design.','original'),
('127.412.d.14.D',4,'A final prototype is expected to be closer to the finished product than an early prototype in:','["packaging only", "function and appearance", "price tag", "name"]'::jsonb,1,'Fidelity increases over time.','original'),
('127.412.d.14.E',3,'A bill of materials lists every part and the:','["weather", "team mood", "quantity needed", "owner''s hobbies"]'::jsonb,2,'BOMs support purchasing and assembly.','original'),
('127.412.d.14.E',4,'Final product documents such as an assembly model help others to:','["forget the design", "ignore the design", "delay", "build or manufacture the product"]'::jsonb,3,'Documents transfer the design.','original'),
('127.412.d.14.F',3,'Requirements often change between early and final prototypes as the team:','["learns from testing", "stops working", "loses interest", "forgets goals"]'::jsonb,0,'Learning refines requirements.','original'),
('127.412.d.14.F',4,'Explaining how a requirement changed, and why, shows that the design process is:','["finished", "evidence-driven", "accidental", "random"]'::jsonb,1,'Changes are justified by data.','original'),
('127.412.d.15.A',3,'Analyzing simulation results can lead to new requirements, such as for:','["a longer name", "extra jokes", "added support", "more paint"]'::jsonb,2,'Results expose needs.','original'),
('127.412.d.15.A',4,'If a simulation shows stress above the allowable limit, the team should document a requirement to:','["hide the result", "raise the limit", "ignore it", "reduce stress in that area"]'::jsonb,3,'Documentation drives redesign.','original'),
('127.412.d.15.B',3,'Using a report template for tests makes results:','["consistent and easy to compare", "unnecessary", "secret", "harder to read"]'::jsonb,0,'Templates standardize reporting.','original'),
('127.412.d.15.B',4,'A test report should list the test setup, results, and:','["jokes", "conclusions", "dates of lunch", "brand names only"]'::jsonb,1,'Reports state what was learned.','original'),
('127.412.d.15.C',3,'A test designed to validate a functional requirement should measure:','["the color", "the room temperature only", "the function stated in the requirement", "something unrelated"]'::jsonb,2,'Tests should match requirements.','original'),
('127.412.d.15.C',4,'A requirement says a hinge must open 5000 times. A valid test would:','["open it once", "look at it", "weigh it", "cycle the hinge 5000 times and inspect it"]'::jsonb,3,'Test the stated condition.','original'),
('127.412.d.15.D',3,'Engineering design is iterative because early results often show the need to:','["revise earlier steps", "stop at once", "avoid change", "skip ahead"]'::jsonb,0,'Iteration improves designs.','original'),
('127.412.d.15.D',4,'Repeating steps of design after test failures is not wasted effort because each pass:','["delays quality", "improves understanding and the design", "hides errors", "wastes materials only"]'::jsonb,1,'Each loop adds knowledge.','original'),
('127.412.d.15.E',3,'Continuous improvement means repeatedly making:','["only huge changes", "no changes", "small refinements", "random changes"]'::jsonb,2,'Improvement is ongoing.','original'),
('127.412.d.15.E',4,'Design iteration and continuous improvement are related because both use feedback to:','["stop work", "add complexity", "avoid testing", "make something better"]'::jsonb,3,'Feedback drives improvement.','original'),
('127.412.d.16.A',3,'An initial project budget includes costs for raw materials, purchased parts, and:','["tools and labor", "weather", "gossip", "gifts only"]'::jsonb,0,'Budgets cover all costs.','original'),
('127.412.d.16.A',4,'Adding a contingency amount to a budget protects against:','["good luck", "unexpected costs", "savings", "early finish"]'::jsonb,1,'Contingency covers surprises.','original'),
('127.412.d.16.B',3,'A Bill of Materials cost report multiplies each part''s unit cost by its quantity and then:','["divides by color", "subtracts the labor", "adds the results", "ignores quantities"]'::jsonb,2,'The total is the sum of line costs.','original'),
('127.412.d.16.B',4,'Three brackets cost 4 dollars each and 10 screws cost 0.50 dollars each. The BOM cost is:','["5 dollars", "12.50 dollars", "22 dollars", "17 dollars"]'::jsonb,3,'12 + 5 = 17.','original'),
('127.412.d.16.C',3,'Comparing the final build cost with the estimated budget shows where the team:','["over- or under-estimated", "won a prize", "lost data", "ignored the budget"]'::jsonb,0,'Differences reveal estimation errors.','original'),
('127.412.d.16.C',4,'A team estimated 200 dollars but spent 250 dollars. The difference of 50 dollars is called a:','["savings", "cost overrun", "bonus", "profit"]'::jsonb,1,'Spending exceeded the estimate.','original'),
('127.412.d.16.D',3,'Monitoring a budget during a project means regularly comparing:','["weather to the plan", "names to the plan", "spending to the plan", "colors to the plan"]'::jsonb,2,'Tracking prevents surprises.','original'),
('127.412.d.16.D',4,'If prices rise for a key material, the manager should update the:','["date of birth", "logo", "design name", "budget and inform the team"]'::jsonb,3,'Budgets must reflect reality.','original'),
('127.412.d.16.E',3,'A budget status report shows how much has been spent and how much:','["remains", "is hidden", "is rumored", "is invented"]'::jsonb,0,'Spenddown tracks remaining funds.','original'),
('127.412.d.16.E',4,'A report that shows spending far ahead of progress should include an explanation of:','["the weather", "the cause of the difference", "team hobbies", "paint choices"]'::jsonb,1,'Reports explain variances.','original'),
('127.412.d.16.F',3,'Budget tracking in design projects is important because it helps prevent:','["finishing early", "more testing", "running out of money before finishing", "lower quality"]'::jsonb,2,'Tracking controls spending.','original'),
('127.412.d.16.F',4,'Tracking costs over time helps a team make better estimates on:','["past weather", "previous holidays", "old lunches", "future projects"]'::jsonb,3,'History improves estimating.','original'),
('127.413.d.1',3,'An aerospace engineer finds a flaw in a flight-critical part after it has been installed. The ethical action is to:','["report it immediately so it can be corrected", "hope it holds", "wait until the next inspection", "keep it secret"]'::jsonb,0,'Safety comes before schedule.','original'),
('127.413.d.1',4,'An aerospace engineer is asked to sign off on a test that was not performed. The ethical response is to:','["sign and hope", "refuse to sign", "delete the request", "sign quickly"]'::jsonb,1,'Honest records protect lives.','original'),
('127.413.d.2.A',3,'Defining the problem clearly at the start of an aerospace design project helps the team to:','["avoid research", "skip testing", "focus on the right needs", "choose a name"]'::jsonb,2,'A clear problem guides the work.','original'),
('127.413.d.2.A',4,'A problem statement for a drone design should include what it must do and its:','["logo", "theme song", "color", "constraints"]'::jsonb,3,'Constraints bound the solution.','original'),
('127.413.d.2.B',3,'The research stage of design involves studying existing aircraft and:','["relevant principles and data", "unrelated jokes", "paint colors", "lunch menus"]'::jsonb,0,'Research informs the design.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_65_v1'
from (values
('127.413.d.2.B',4,'Reading accident reports during research helps designers to avoid repeating:','["trends in fashion", "past failures", "price lists", "successes"]'::jsonb,1,'History teaches safety.','original'),
