('127.413.d.2.D',3,'Selecting a concept for detailed development means comparing ideas against the:','["requirements", "parking", "lunch plans", "weather"]'::jsonb,0,'Requirements drive selection.','original'),
('127.413.d.2.D',4,'A team chooses the concept with the best balance of performance, cost, and:','["slogan", "safety", "color", "mood"]'::jsonb,1,'Trade-offs guide choices.','original'),
('127.413.d.2.E',3,'A technical drawing differs from a sketch by including:','["colors only", "jokes", "precise dimensions and standards", "signatures"]'::jsonb,2,'Technical drawings follow standards.','original'),
('127.413.d.2.E',4,'A scale model of a wing in a wind tunnel is a:','["report", "budget", "contract", "physical model used for testing"]'::jsonb,3,'Models test concepts.','original'),
