from (values
('127.413.d.16.B',3,'Increasing an orbit''s eccentricity makes the orbit more:','["small", "slow", "elongated", "circular"]'::jsonb,2,'Eccentricity measures elongation.','original'),
('127.413.d.16.B',4,'An orbit with an eccentricity of 0 is:','["elongated", "parabolic", "impossible", "circular"]'::jsonb,3,'Zero means a circle.','original'),
('127.413.d.16.C',3,'A communications satellite that must stay over one spot on Earth needs a:','["geostationary orbit", "low orbit", "suborbital arc", "polar orbit"]'::jsonb,0,'Geostationary orbits match Earth''s rotation.','original'),
('127.413.d.16.C',4,'A satellite that must photograph the entire Earth over time may use a:','["suborbital arc", "polar orbit", "geostationary orbit", "equatorial orbit only"]'::jsonb,1,'Polar orbits cover all latitudes.','original'),
('127.413.d.16.D',3,'Operating in space means exposure to extreme temperature changes and:','["rain", "fog", "radiation", "wind"]'::jsonb,2,'Space is a harsh environment.','original'),
('127.413.d.16.D',4,'Because there is no air in space, heat leaves a spacecraft mainly by:','["convection", "conduction through air", "wind", "radiation"]'::jsonb,3,'Radiative cooling dominates.','original'),
('127.413.d.16.E',3,'A common way to reach orbit is with a multi-stage:','["rocket", "balloon", "glider", "bicycle"]'::jsonb,0,'Rockets provide the needed speed.','original'),
('127.413.d.16.E',4,'A capsule returning from orbit slows down using atmospheric drag, a heat shield, and often:','["wheels only", "parachutes", "wings only", "skis"]'::jsonb,1,'Parachutes slow the final descent.','original'),
('127.413.d.16.F',3,'A growing trend in space flight is reusable launch vehicles, which can:','["increase costs", "need no fuel", "lower launch costs", "avoid testing"]'::jsonb,2,'Reuse cuts the cost per launch.','original'),
('127.413.d.16.F',4,'Small satellites known as CubeSats are growing in use because they are:','["impossible to launch", "very expensive", "huge", "low-cost and quick to build"]'::jsonb,3,'CubeSats are affordable.','original'),
('127.413.d.17.A',3,'Aerospace engineers contribute to automotive design by improving:','["aerodynamics and materials", "paint names", "insurance", "dealer locations"]'::jsonb,0,'Cars benefit from aero know-how.','original'),
('127.413.d.17.A',4,'Streamlining the shape of a car reduces drag and therefore improves:','["engine size", "fuel economy", "wind noise only", "tire price"]'::jsonb,1,'Less drag saves energy.','original'),
('127.413.d.17.B',3,'Commercial uses of aerospace design include airliners, satellites, and:','["pillows", "books", "wind turbines", "picture frames"]'::jsonb,2,'Aerodynamics is used in turbines.','original'),
('127.413.d.17.B',4,'Lightweight composites first used in aircraft are now also found in:','["only rockets", "only bricks", "only glass", "bicycles and sporting goods"]'::jsonb,3,'Composites spread to consumer goods.','original'),
('127.413.d.17.C',3,'A household item impacted by aerodynamics is a:','["ceiling fan", "lamp base", "rug", "couch"]'::jsonb,0,'Fan blades act like airfoils.','original'),
('127.413.d.17.C',4,'A vacuum cleaner, hair dryer, and ceiling fan all depend on moving:','["paper", "air", "sand", "glass"]'::jsonb,1,'Airflow is central to each.','original'),
('127.413.d.18.A',3,'Aircraft navigation systems help the pilot determine the aircraft''s:','["paint", "name", "position and route", "lunch"]'::jsonb,2,'Navigation finds position.','original'),
('127.413.d.18.A',4,'A communication system lets pilots talk to:','["the passengers'' families", "the engine", "the weather only", "air traffic control"]'::jsonb,3,'Radios connect pilots and controllers.','original'),
('127.413.d.18.B',3,'Satellite-based navigation, such as GPS, is one implementation of aircraft:','["navigation systems", "fuel systems", "seating systems", "paint systems"]'::jsonb,0,'GPS uses satellites.','original'),
('127.413.d.18.B',4,'An autopilot is a system that can:','["refuel the aircraft", "fly the aircraft along a set course", "paint the aircraft", "build the aircraft"]'::jsonb,1,'Autopilots hold heading and altitude.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
